			{"id": "c", "tags": {"env": "prod"}, "disabled": true}
		],
		"include": [{"env": "prod", "region": "us"}, {"env": "dev"}]
	}`
	shuffled := `{
		"app": "app", "revision": "r1", "image": "img", "batchSize": 2,
		"clusters": [
			{"id": "c", "tags": {"env": "prod"}, "disabled": true},
			{"id": "b", "tags": {"env": "dev"}},
