64	func planSummary(p ReleasePlan) string {
65		var b strings.Builder
66		b.WriteString(p.App.Name + "/" + p.App.Revision + "/" + p.App.Image)
67		for _, batch := range p.Batches {
68			b.WriteString("|b" + strings.Join(batch.Clusters, ","))
69		}
70		for _, e := range p.Excluded {
71			b.WriteString("|x" + e.ID + ":" + e.Reason)
72		}
73		return b.String()
74	}
