76	// A huge number in a business field is judged by that field's own rules:
77	// batchSize must stay a positive integer, tag/condition values must stay
78	// strings — never reported as a JSON format error, never truncated or
79	// replaced by a default.
80	func TestParse_HugeNumberInBusinessFieldGivesFieldError(t *testing.T) {
